//! Get a download URL for a private file.
//!
//! The request waits up to ten seconds for the response and returns a download URL
//! generated by the upstream; validity and permissions are determined by the upstream.

use crate::error::Result;
use crate::prelude::BotContext;
use serde_derive::{Deserialize, Serialize};
use tokio::time::Duration;

/// Download URL for a private file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivateFileUrl {
    /// File download URL; validity and permissions are determined by the upstream.
    pub url: String,
}

impl BotContext {
    /// Request a download URL for a private file and wait for the response data within ten
    /// seconds.
    ///
    /// # Arguments
    ///
    /// - `file_id`: File ID.
    /// - `user_id`: QQ number of the user who owns the file; `None` is sent as JSON `null`,
    ///   and whether the upstream accepts it depends on the implementation. This parameter
    ///   accepts `i64` or `Option<i64>`.
    ///
    /// # Errors
    ///
    /// Returns [`crate::error::Error::StateError`] when the current connection is
    /// unavailable or `retcode` is non-zero; returns
    /// [`crate::error::Error::WebSocketError`] when the WebSocket send fails; returns
    /// [`crate::error::Error::TimeoutError`] when no response is received within ten
    /// seconds; returns [`crate::error::Error::JsonError`] when the response cannot be
    /// deserialized into [`PrivateFileUrl`].
    pub async fn get_private_file_url(
        &self,
        file_id: &str,
        user_id: impl Into<Option<i64>>,
    ) -> Result<PrivateFileUrl> {
        let response = self
            .websocket_send(
                "get_private_file_url",
                serde_json::json!({
                    "file_id": file_id,
                    "user_id": user_id.into(),
                }),
            )
            .await?;
        let response = response.data(Duration::from_secs(10)).await?;
        let group_member_info: PrivateFileUrl = serde_json::from_value(response)?;
        Ok(group_member_info)
    }
}
